  /// should the thresholded image be deglitched? Only useful for
  /// very noisy images
  @ffi.Int()
  external int deglitch;
}

typedef dart_run_callback_0 = ffi.Pointer<ffi.NativeFunction<dart_run_callback_0Function>>;
typedef dart_run_callback_0Function = ffi.Void Function();
typedef Dartdart_run_callback_0Function = void Function();

final class image_f32 extends ffi.Struct {
