  @ffi.Int32()
  external int height;

  /// floats per line
  @ffi.Int32()
  external int stride;

  /// indexed as buf[y*stride + x]
  external ffi.Pointer<ffi.Float> buf;
}

typedef image_f32_t = image_f32;

final class image_u8 extends ffi.Struct {
  @ffi.Int32()
  external int width;

  @ffi.Int32()
  external int height;

  @ffi.Int32()
  external int stride;

  external ffi.Pointer<ffi.Uint8> buf;
}

final class image_u8_lut extends ffi.Struct {
  /// When drawing, we compute the squared distance between a given pixel and a filled region.
  /// int idx = squared_distance * scale;
  /// We then index into values[idx] to obtain the color. (If we must index beyond nvalues,
  /// no drawing is performed.)
  @ffi.Float()
  external double scale;

  @ffi.Int()
  external int nvalues;

  external ffi.Pointer<ffi.Uint8> values;
}

typedef image_u8_lut_t = image_u8_lut;

/// to support conversions between different types, we define all image
/// types at once. Type-specific implementations can then #include this
/// file, assured that the basic types of each image are known.
typedef image_u8_t = image_u8;

/// Creates a double matrix with the Cholesky lower triangular matrix
/// of A. A must be symmetric, positive definite. It is the caller's
/// responsibility to call matd_destroy() on the returned matrix.
/// /
/// //matd_t *matd_cholesky(const matd_t *A);
final class matd_chol_t extends ffi.Struct {
  @ffi.Int()
  external int is_spd;

  external ffi.Pointer<matd_t> u;
}

/// All square matrices (even singular ones) have a partially-pivoted
/// LU decomposition such that A = PLU, where P is a permutation
/// matrix, L is a lower triangular matrix, and U is an upper
/// triangular matrix.
final class matd_plu_t extends ffi.Struct {
  /// was the input matrix singular? When a zero pivot is found, this
  /// flag is set to indicate that this has happened.
  @ffi.Int()
  external int singular;

  /// permutation indices
  external ffi.Pointer<ffi.UnsignedInt> piv;

  /// either +1 or -1
  @ffi.Int()
  external int pivsign;

  /// combined L and U matrices, permuted so they can be triangular.
  external ffi.Pointer<matd_t> lu;
}

final class matd_svd_t extends ffi.Struct {
  external ffi.Pointer<matd_t> U;

  external ffi.Pointer<matd_t> S;

  external ffi.Pointer<matd_t> V;
}

/// Defines a matrix structure for holding double-precision values with
/// data in row-major order (i.e. index = row*ncols + col).
///
/// nrows and ncols are 1-based counts with the exception that a scalar (non-matrix)
/// is represented with nrows=0 and/or ncols=0.
final class matd_t extends ffi.Struct {
  @ffi.UnsignedInt()
  external int nrows;

  @ffi.UnsignedInt()
  external int ncols;

  external ffi.Pointer<ffi.Double> data;
}

typedef pthread_mutex_t = CRITICAL_SECTION;

final class quad extends ffi.Struct {
  /// corners
  @ffi.Array.multi([4, 2])
